1	export type ProcessingState = "draft" | "scheduled" | "sending" | "complete";
2	
3	export interface RecordState {
4	  campaignId: string;
5	  processingState: ProcessingState;
6	}
7	
8	/** Marketing automation processing updates published to the campaign dashboard. */
9	export function applyProcessingState(
10	  record: RecordState,
11	  state: ProcessingState,
12	  publish: (frame: object) => void,
13	): void {
14	  record.processingState = state;
15	  publish({
16	    resource: { id: record.campaignId, processing_status: record.processingState },
17	    type: "marketing_campaign",
18	    event: "status_changed",
19	  });
20	}
